#include <stdio.h>
#include <string.h>

#define MAX_STUDENTS 200

typedef struct {
    int id;
    char name[32];
    float gpa;
} Student;

typedef struct {
    Student records[MAX_STUDENTS];
    int count;
} StudentSystem;

int find_index(StudentSystem *sys, int id) {
    for (int i = 0; i < sys->count; i++) {
        if (sys->records[i].id == id) return i;
    }
    return -1;
}

void add_student(StudentSystem *sys, int id, const char *name, float gpa) {
    if (find_index(sys, id) != -1) {
        printf("ALREADY_EXISTS\n");
        return;
    }
    if (sys->count < MAX_STUDENTS) {
        sys->records[sys->count].id = id;
        strncpy(sys->records[sys->count].name, name, 31);
        sys->records[sys->count].name[31] = '\0';
        sys->records[sys->count].gpa = gpa;
        sys->count++;
        printf("ADDED\n");
    }
}

void find_student(StudentSystem *sys, int id) {
    int idx = find_index(sys, id);
    if (idx == -1) {
        printf("NOT_FOUND\n");
    } else {
        printf("%s %.2f\n", sys->records[idx].name, sys->records[idx].gpa);
    }
}

void delete_student(StudentSystem *sys, int id) {
    int idx = find_index(sys, id);
    if (idx == -1) {
        printf("NOT_FOUND\n");
    } else {
        for (int i = idx; i < sys->count - 1; i++) {
            sys->records[i] = sys->records[i + 1];
        }
        sys->count--;
        printf("DELETED\n");
    }
}

void update_student(StudentSystem *sys, int id, float new_gpa) {
    int idx = find_index(sys, id);
    if (idx == -1) {
        printf("NOT_FOUND\n");
    } else {
        sys->records[idx].gpa = new_gpa;
        printf("UPDATED\n");
    }
}

void top_student(StudentSystem *sys) {
    if (sys->count == 0) {
        printf("EMPTY\n");
        return;
    }
    int best_idx = 0;
    for (int i = 1; i < sys->count; i++) {
        if (sys->records[i].gpa > sys->records[best_idx].gpa) {
            best_idx = i;
        } else if (sys->records[i].gpa == sys->records[best_idx].gpa) {
            if (sys->records[i].id < sys->records[best_idx].id) {
                best_idx = i;
            }
        }
    }
    printf("%s %.2f\n", sys->records[best_idx].name, sys->records[best_idx].gpa);
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    StudentSystem sys;
    sys.count = 0;

    char op[16];
    for (int i = 0; i < n; i++) {
        if (scanf("%s", op) != 1) break;
        if (strcmp(op, "ADD") == 0) {
            int id;
            char name[32];
            float gpa;
            scanf("%d %s %f", &id, name, &gpa);
            add_student(&sys, id, name, gpa);
        } else if (strcmp(op, "FIND") == 0) {
