#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[32];
    int score;
    int age;
} Candidate;

int compare_candidates(const void *a, const void *b) {
    const Candidate *c1 = (const Candidate *)a;
    const Candidate *c2 = (const Candidate *)b;

    // 1. Score descending
    if (c1->score != c2->score) {
        return (c2->score - c1->score);
    }
    // 2. Age ascending
    if (c1->age != c2->age) {
        return (c1->age - c2->age);
    }
    // 3. Name lexicographical ascending
    return strcmp(c1->name, c2->name);
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Candidate *arr = (Candidate *)malloc(n * sizeof(Candidate));
    for (int i = 0; i < n; i++) {
        scanf("%s %d %d", arr[i].name, &arr[i].score, &arr[i].age);
    }

    qsort(arr, n, sizeof(Candidate), compare_candidates);

    for (int i = 0; i < n; i++) {
        printf("%s %d %d\n", arr[i].name, arr[i].score, arr[i].age);
    }

    free(arr);
    return 0;
}

