#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int id;
    int value;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
} LinkedList;

void list_push_front(LinkedList *list, int id, int val) {
    Node *node = (Node *)malloc(sizeof(Node));
    node->id = id;
    node->value = val;
    node->next = list->head;
    list->head = node;
}

void list_push_back(LinkedList *list, int id, int val) {
    Node *node = (Node *)malloc(sizeof(Node));
    node->id = id;
    node->value = val;
    node->next = NULL;
    if (list->head == NULL) {
        list->head = node;
        return;
    }
    Node *curr = list->head;
    while (curr->next != NULL) {
        curr = curr->next;
    }
    curr->next = node;
}

void list_delete_id(LinkedList *list, int id) {
    if (list->head == NULL) {
        printf("NOT_FOUND\n");
        return;
    }
    if (list->head->id == id) {
        Node *temp = list->head;
        list->head = list->head->next;
        free(temp);
        printf("DELETED\n");
        return;
    }
    Node *curr = list->head;
    while (curr->next != NULL && curr->next->id != id) {
        curr = curr->next;
    }
    if (curr->next != NULL) {
        Node *temp = curr->next;
        curr->next = curr->next->next;
        free(temp);
        printf("DELETED\n");
    } else {
        printf("NOT_FOUND\n");
    }
}

void list_update_val(LinkedList *list, int id, int new_val) {
    Node *curr = list->head;
    while (curr != NULL) {
        if (curr->id == id) {
            curr->value = new_val;
            printf("UPDATED\n");
            return;
        }
        curr = curr->next;
    }
    printf("NOT_FOUND\n");
}

void list_print(LinkedList *list) {
    if (list->head == NULL) {
        printf("EMPTY\n");
        return;
    }
    Node *curr = list->head;
    while (curr != NULL) {
        printf("[%d:%d]->", curr->id, curr->value);
        curr = curr->next;
    }
    printf("NULL\n");
}

void list_sum(LinkedList *list) {
    long long total = 0;
    Node *curr = list->head;
    while (curr != NULL) {
        total += curr->value;
        curr = curr->next;
    }
    printf("%lld\n", total);
}

void list_free(LinkedList *list) {
    Node *curr = list->head;
    while (curr != NULL) {
        Node *next = curr->next;
        free(curr);
        curr = next;
    }
    list->head = NULL;
}

int main() {
    int q;
    if (scanf("%d", &q) != 1) return 0;

    LinkedList list = { NULL };

    char cmd[16];
    for (int i = 0; i < q; i++) {
        if (scanf("%s", cmd) != 1) break;
        if (strcmp(cmd, "PUSH_FRONT") == 0) {
            int id, val;
            scanf("%d %d", &id, &val);
            list_push_front(&list, id, val);
        } else if (strcmp(cmd, "PUSH_BACK") == 0) {
            int id, val;
            scanf("%d %d", &id, &val);
            list_push_back(&list, id, val);
        } else if (strcmp(cmd, "DELETE_ID") == 0) {
            int id;
            scanf("%d", &id);
            list_delete_id(&list, id);
        } else if (strcmp(cmd, "UPDATE_VAL") == 0) {
