#include <stdio.h>
#include <string.h>

typedef enum {
    STATE_IDLE,
    STATE_COIN_INSERTED
} VendingState;

typedef struct {
    VendingState state;
    int stock;
    int balance;
} VendingMachine;

void vm_init(VendingMachine *vm, int initial_stock) {
    vm->state = STATE_IDLE;
    vm->stock = initial_stock;
    vm->balance = 0;
}

void vm_insert(VendingMachine *vm, int amount) {
    vm->balance += amount;
    vm->state = STATE_COIN_INSERTED;
    printf("BALANCE: %d STATE: COIN_INSERTED\n", vm->balance);
}

void vm_select(VendingMachine *vm) {
    if (vm->state == STATE_IDLE) {
        printf("INVALID_ACTION\n");
        return;
    }
    if (vm->stock == 0) {
        int refund = vm->balance;
        vm->balance = 0;
        vm->state = STATE_IDLE;
        printf("OUT_OF_STOCK REFUND: %d STATE: IDLE\n", refund);
        return;
    }
    if (vm->balance < 50) {
        printf("INSUFFICIENT_FUNDS NEED: %d\n", 50 - vm->balance);
        return;
    }
    vm->stock--;
    int change = vm->balance - 50;
    vm->balance = 0;
    vm->state = STATE_IDLE;
    printf("DISPENSING CHANGE: %d\n", change);
}

void vm_refund(VendingMachine *vm) {
    if (vm->state == STATE_COIN_INSERTED) {
        int refund = vm->balance;
        vm->balance = 0;
        vm->state = STATE_IDLE;
        printf("REFUND: %d STATE: IDLE\n", refund);
    } else {
        printf("NO_COINS\n");
    }
}

void vm_restock(VendingMachine *vm, int count) {
    vm->stock += count;
    printf("STOCK: %d\n", vm->stock);
}

int main() {
    int initial_stock;
    if (scanf("%d", &initial_stock) != 1) return 0;

