    for (int i = 0; i < n; i++) {
        if (scanf("%s", cmd) != 1) break;
        if (strcmp(cmd, "INSERT") == 0) {
            int amount;
            scanf("%d", &amount);
            vm_insert(&vm, amount);
        } else if (strcmp(cmd, "SELECT") == 0) {
            vm_select(&vm);
        } else if (strcmp(cmd, "REFUND") == 0) {
            vm_refund(&vm);
        } else if (strcmp(cmd, "RESTOCK") == 0) {
            int count;
            scanf("%d", &count);
            vm_restock(&vm, count);
        }
    }
    return 0;
}

