#include <stdio.h>
#include <string.h>

typedef int (*OpFunc)(int a, int b, int *error_code);

int op_add(int a, int b, int *err) {
    return a + b;
}

int op_sub(int a, int b, int *err) {
    return a - b;
}

int op_mul(int a, int b, int *err) {
    return a * b;
}

int op_div(int a, int b, int *err) {
    if (b == 0) {
        *err = 1;
        return 0;
    }
    return a / b;
}

int op_mod(int a, int b, int *err) {
    if (b == 0) {
        *err = 1;
        return 0;
    }
    return a % b;
}

int op_and(int a, int b, int *err) {
    return a & b;
}

int op_or(int a, int b, int *err) {
    return a | b;
}

int op_xor(int a, int b, int *err) {
    return a ^ b;
}

typedef struct {
    char name[16];
    OpFunc func;
} CommandEntry;

static const CommandEntry dispatch_table[] = {
    {"ADD", op_add},
    {"SUB", op_sub},
    {"MUL", op_mul},
    {"DIV", op_div},
    {"MOD", op_mod},
    {"AND", op_and},
    {"OR",  op_or},
    {"XOR", op_xor}
};

static const int NUM_COMMANDS = sizeof(dispatch_table) / sizeof(dispatch_table[0]);

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    char op[16];
    int a, b;
    for (int i = 0; i < n; i++) {
        if (scanf("%s %d %d", op, &a, &b) != 3) break;

        int found = 0;
        for (int j = 0; j < NUM_COMMANDS; j++) {
            if (strcmp(dispatch_table[j].name, op) == 0) {
                int err = 0;
                int res = dispatch_table[j].func(a, b, &err);
                if (err != 0) {
                    printf("ERROR: DIVISION_BY_ZERO\n");
                } else {
                    printf("%d\n", res);
                }
                found = 1;
                break;
            }
        }
        if (!found) {
            printf("ERROR: UNKNOWN_OP\n");
        }
    }
    return 0;
}

