#include <stdio.h>
#include <string.h>

void get_type_info(const char *type, int *size, int *align) {
    if (strcmp(type, "char") == 0) {
        *size = 1; *align = 1;
    } else if (strcmp(type, "short") == 0) {
        *size = 2; *align = 2;
    } else if (strcmp(type, "int") == 0) {
        *size = 4; *align = 4;
    } else if (strcmp(type, "float") == 0) {
        *size = 4; *align = 4;
    } else if (strcmp(type, "double") == 0) {
        *size = 8; *align = 8;
    } else if (strcmp(type, "long_long") == 0) {
        *size = 8; *align = 8;
    } else if (strcmp(type, "pointer") == 0) {
        *size = 8; *align = 8;
    } else {
        *size = 1; *align = 1;
    }
}

int main() {
    int m;
    if (scanf("%d", &m) != 1) return 0;

    int current_offset = 0;
    int max_align = 1;
    int total_padding = 0;

    char type[32];
    for (int i = 0; i < m; i++) {
        scanf("%s", type);
        int size, align;
        get_type_info(type, &size, &align);

        if (align > max_align) {
            max_align = align;
        }

        int pad = (align - (current_offset % align)) % align;
        total_padding += pad;
        current_offset += pad;

        printf("FIELD %d: %s OFFSET: %d PAD: %d\n", i, type, current_offset, pad);
        current_offset += size;
    }

    int tail_pad = (max_align - (current_offset % max_align)) % max_align;
    total_padding += tail_pad;
    int total_size = current_offset + tail_pad;

    printf("TOTAL_SIZE: %d TOTAL_PADDING: %d ALIGNMENT: %d\n", total_size, total_padding, max_align);
    return 0;
}
